import os


def index_files(root, extensions=None):
    """Index files under ``root``.

    Returns a mapping of file name to size in bytes.
    """
    if extensions is not None:
        extensions = tuple(extensions)
    result = {}
    for dirpath, dirnames, filenames in os.walk(root):
        for name in filenames:
            if extensions is None or name.endswith(extensions):
                result[name] = os.path.getsize(os.path.join(dirpath, name))
    return result

