import os
import tempfile
import unittest

from file_index import index_files


class IndexFilesTests(unittest.TestCase):
    def setUp(self):
        self._tmp = tempfile.TemporaryDirectory()
        self.root = self._tmp.name

    def tearDown(self):
        self._tmp.cleanup()

    def _write(self, rel_path, data=b""):
        parts = rel_path.split("/")
        full = os.path.join(self.root, *parts)
        parent = os.path.dirname(full)
        if parent:
            os.makedirs(parent, exist_ok=True)
        with open(full, "wb") as handle:
            handle.write(data)
        return full

    def test_empty_directory_returns_empty_mapping(self):
        self.assertEqual(index_files(self.root), {})

    def test_single_file_reports_size(self):
        self._write("alpha.txt", b"hello")
        self.assertEqual(index_files(self.root), {"alpha.txt": 5})

    def test_nested_files_use_relative_paths(self):
        self._write("pkg/mod.py", b"123")
        self._write("pkg/deep/data.bin", b"12345678")
        expected = {
            os.path.join("pkg", "mod.py"): 3,
            os.path.join("pkg", "deep", "data.bin"): 8,
        }
        self.assertEqual(index_files(self.root), expected)

    def test_extension_filter_keeps_only_matches(self):
        self._write("a.txt", b"aa")
        self._write("b.py", b"bbb")
        self._write("notes.md", b"m")
        self.assertEqual(index_files(self.root, [".py"]), {"b.py": 3})

    def test_extension_filter_accepts_missing_dot(self):
        self._write("a.txt", b"aa")
        self._write("b.py", b"bbb")
        self.assertEqual(index_files(self.root, ["py"]), {"b.py": 3})

    def test_extension_filter_is_case_insensitive(self):
        self._write("script.PY", b"z")
        self.assertEqual(index_files(self.root, [".py"]), {"script.PY": 1})

    def test_empty_extension_filter_returns_empty_mapping(self):
        self._write("a.txt", b"a")
        self.assertEqual(index_files(self.root, []), {})

    def test_missing_root_raises_file_not_found(self):
        missing = os.path.join(self.root, "does-not-exist")
        with self.assertRaises(FileNotFoundError):
            index_files(missing)


if __name__ == "__main__":
    unittest.main()
